mapper.select:
SELECT order_row.order_no, customer_row.customer_no, order_row.amount, order_row.status, order_row.metadata ->> 'channel' AS channel, order_row.metadata::text AS metadata, order_row.created_at FROM purchase_orders order_row JOIN customers customer_row ON customer_row.id = order_row.customer_id WHERE order_row.tenant_id = #{tenantId}
AND EXISTS ( SELECT 1 FROM order_items item_row WHERE item_row.order_id = order_row.id AND item_row.search_vector @@ plainto_tsquery('simple', #{keyword}) )
AND order_row.metadata ->> 'channel' = #{channel}
ORDER BY order_row.created_at DESC LIMIT #{limit}
